draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // draw fruit
  ctx.fillStyle = 'red';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw leaves
  ctx.fillStyle = 'green';
  ctx.beginPath();
  ctx.arc(W/2 + 30 * Math.sin(t), H/2 - 30 * Math.cos(t), 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // draw stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 + 50, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 70);
  ctx.lineTo(W/2 - 100, H/2 + 150);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 100);
  ctx.lineTo(W/2 - 80, H/2 + 120);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 + 100);
  ctx.lineTo(W/2 - 120, H/2 + 120);
  ctx.stroke();

  // draw text
  ctx.font = '30px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'top';
  ctx.fillText('70% of health', W/2, H/2 + 200);
  ctx.fillText('comes from nutrition', W/2, H/2 + 230);

  ctx.restore();
}
